INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch05$PT143-S1-Q1$batch05$, 143, 1, 1, $batch05$Necessary Assumption$batch05$, $batch05$Pundit: Our city made a mistake when it sold a private company the rights to assess and collect parking fees. The private company raised parking fees and so has been able to reap profits far greater than what it paid for the rights to assess and collect the fees. If the city had not sold the rights, then that money would have gone to the city.$batch05$, $batch05$The pundit’s argument requires the assumption that$batch05$, $batch05$B$batch05$, true, $batch05$Batch 05; question text from local bank.$batch05$ FROM lr_sections s WHERE s.preptest=143 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT143-S1-Q1$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$A$batch05$, $batch05$other private companies would have been willing to pay for the rights to assess and collect parking fees$batch05$, $batch05$Not Necessary$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT143-S1-Q1$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$A$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$B$batch05$, $batch05$the city could have raised parking fees had it not sold the rights$batch05$, $batch05$Correct$batch05$, true FROM lr_questions q WHERE q.qid=$batch05$PT143-S1-Q1$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$B$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$C$batch05$, $batch05$municipal functions like assessing and collecting parking fees should always be handled directly by the municipality in question$batch05$, $batch05$Too Strong$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT143-S1-Q1$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$C$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$D$batch05$, $batch05$the revenue from parking fees is not the only factor that cities need to consider in setting the rates for parking fees$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT143-S1-Q1$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$D$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$E$batch05$, $batch05$private companies assess and collect parking fees more efficiently than cities do$batch05$, $batch05$Weakens$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT143-S1-Q1$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$E$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT143-S1-Q1$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$The city made a mistake selling the parking fee rights, because that money would have gone to the city.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$The private company raised fees and earned far more than it paid for the rights.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The company's big profits came from *raising fees*. The pundit assumes the city would have earned that same money. But that only follows if the city could have raised fees the same way. If it could not (say, it lacked the authority or the political room), the city would never have seen those profits.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A defender: the city could have done what the company did and raised the fees.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT143-S1-Q1$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Other bidders do not matter. The question is whether the city could have kept the money itself.$batch05$), ($batch05$B$batch05$, $batch05$Negate it: "the city *could not* have raised parking fees." Then the company's extra profits came from something the city could never have done, and that money would not have gone to the city.$batch05$), ($batch05$C$batch05$, $batch05$"Always" handle it directly is a sweeping rule. The pundit only claims this one sale was a mistake.$batch05$), ($batch05$D$batch05$, $batch05$Other factors in setting rates do not affect whether the city could have earned this money.$batch05$), ($batch05$E$batch05$, $batch05$If private companies collect fees more efficiently, the city might have earned less than the company did. That is a point against the pundit.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT143-S1-Q1$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
